// Flat search across sections: returns [{ section, item }] matching the query.
export function searchGuide(query) {
  const q = (query || '').trim().toLowerCase()
  if (!q) return []
  const out = []
  GUIDE.forEach((sec) => {
    sec.items.forEach((item) => {
      const hay = `${item.title} ${item.body} ${(item.tags || []).join(' ')}`.toLowerCase()
      if (hay.includes(q)) out.push({ section: sec, item })
    })
  })
  return out
}
